package com.hbm.client.coolingtower;
import com.google.gson.*;import com.hbm.machine.coolingtower.*;import com.hbm.particle.LegacyFluidEffects;import net.minecraft.client.renderer.BlockEntityWithoutLevelRenderer;import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.fml.event.lifecycle.FMLClientSetupEvent;import net.neoforged.fml.loading.FMLPaths;import net.neoforged.neoforge.client.event.*;import net.neoforged.neoforge.client.extensions.common.*;import java.nio.file.*;
@EventBusSubscriber(modid="hbm",value=Dist.CLIENT,bus=EventBusSubscriber.Bus.MOD)
public final class CoolingTowerClient {
 private static boolean particles=true;
 @SubscribeEvent public static void renderers(EntityRenderersEvent.RegisterRenderers event){for(var kind:java.util.List.of(CoolingTowerKind.SMALL,CoolingTowerKind.LARGE))event.registerBlockEntityRenderer(CoolingTowerContent.ENTITIES.get(kind).get(),CoolingTowerRenderer::new);}
 @SubscribeEvent public static void extensions(RegisterClientExtensionsEvent event){for(var kind:java.util.List.of(CoolingTowerKind.SMALL,CoolingTowerKind.LARGE))event.registerItem(new IClientItemExtensions(){private CoolingTowerItemRenderer renderer;@Override public BlockEntityWithoutLevelRenderer getCustomRenderer(){return renderer==null?(renderer=new CoolingTowerItemRenderer(kind)):renderer;}},CoolingTowerContent.ITEM.get(kind).get());}
 @SubscribeEvent public static void setup(FMLClientSetupEvent event){event.enqueueWork(()->{CoolingTowerBlockEntity.clientTick=CoolingTowerClient::tick;var path=FMLPaths.CONFIGDIR.get().resolve("hbmConfig/hbmClient.json");try{Files.createDirectories(path.getParent());var root=Files.isRegularFile(path)?JsonParser.parseString(Files.readString(path)).getAsJsonObject():new JsonObject();if(root.has("COOLING_TOWER_PARTICLES"))particles=root.get("COOLING_TOWER_PARTICLES").getAsBoolean();root.addProperty("COOLING_TOWER_PARTICLES",particles);Files.writeString(path,new GsonBuilder().setPrettyPrinting().create().toJson(root)+"\n");}catch(Exception error){com.mojang.logging.LogUtils.getLogger().error("Cannot load original cooling tower particle setting",error);}});}
 private static void tick(CoolingTowerBlockEntity machine){var level=machine.getLevel();if(!particles||level==null||machine.waterTimer<=0||machine.kind==CoolingTowerKind.CONDENSER)return;var random=level.random;var pos=machine.getBlockPos();if(machine.kind==CoolingTowerKind.SMALL&&level.getGameTime()%2==0){var particle=new LegacyFluidEffects.Tower(1,.5F,4,250+random.nextInt(250));LegacyFluidEffects.tower(level,pos.getX()+.5,pos.getY()+18,pos.getZ()+.5,particle);}else if(machine.kind==CoolingTowerKind.LARGE&&level.getGameTime()%4==0){int life=750+random.nextInt(250);double x=pos.getX()+.5+random.nextDouble()*3-1.5,z=pos.getZ()+.5+random.nextDouble()*3-1.5;LegacyFluidEffects.tower(level,x,pos.getY()+1,z,new LegacyFluidEffects.Tower(.5F,1,10,life));}}
 private CoolingTowerClient(){}
}
